<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Verify payment · LRC LLC</title><style>body{font:15px system-ui;margin:32px;background:#f4f6f8;color:#17212b}main{max-width:800px;margin:auto;background:white;padding:28px;border-radius:14px}label{display:block;margin:12px 0 5px}input{padding:10px;border:1px solid #ccd4da;border-radius:7px;width:100%;box-sizing:border-box}button{padding:12px 18px;background:#126e66;color:white;border:0;border-radius:7px;margin-top:18px}.notice{background:#fff7e5;padding:12px;border-radius:8px}.error{color:#a22}</style></head><body><main><p><a href="{{ route('billing.index') }}">← Rent billing</a></p><h1>Verify {{ $payment->payment_number }}</h1><p>Tenant: {{ $payment->tenant->legal_name }} · Amount: {{ number_format((float)$payment->amount,2) }} RWF</p><p class="notice">Confirm the funds have actually arrived in the appropriate account or cash register. Allocations must total exactly the payment amount and cannot exceed any charge's outstanding balance.</p>@if($errors->any())<ul class="error">@foreach($errors->all() as $error)<li>{{ $error }}</li>@endforeach</ul>@endif<form method="post" action="{{ route('billing.payment.verify',$payment) }}">@csrf<h2>Allocate payment</h2>@foreach($charges as $i=>$charge)<div><label><strong>{{ $charge->charge_number }}</strong> — {{ $charge->billing_period->format('M Y') }} · Outstanding {{ number_format((float)$charge->outstanding_amount,2) }} RWF</label><input type="hidden" name="allocations[{{ $i }}][rent_charge_id]" value="{{ $charge->id }}"><input type="number" min="0" max="{{ $charge->outstanding_amount }}" step=".01" name="allocations[{{ $i }}][amount]" placeholder="Amount to allocate (0 if none)"></div>@endforeach<label>Verification note</label><input name="verification_note" maxlength="2000"><button type="submit">Verify and post allocations</button></form></main></body></html>